(() => {
'use strict';
const KEY='jovabook-essential-demo-v2';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(v)||0);
const uid=p=>p+'_'+crypto.randomUUID().slice(0,8);
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>dateKey(new Date());
const addDays=(key,n)=>{const d=new Date(key+'T12:00:00');d.setDate(d.getDate()+n);return dateKey(d);};
const humanDate=k=>new Date(k+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'});
const mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);
const clock=m=>`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const idFor=n=>n.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,45);
const days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function seedSalon(id,name,slug,color){
 const date=addDays(today(),1);
 const services=[{id:'brows',name:'Brow shape & tint',price:25,duration:30},{id:'lashes',name:'Lash lift',price:55,duration:60},{id:'nails',name:'Gel manicure',price:35,duration:45}];
 return {id,name,slug,color,initials:name.split(' ').slice(0,2).map(x=>x[0]).join(''),email:'hello@example.com',phone:'020 7946 0123',address:'24 High Street, London',about:'A friendly independent salon offering thoughtful treatments and personal care.',owner:'Sam Taylor',hours:{start:'09:00',end:'18:00',days:[1,2,3,4,5,6]},buffer:0,notice:0,services,staff:[{id:'owner',name:'Sam Taylor',role:'Owner',active:true}],customers:[{id:'c1',name:'Alex Morgan',email:'alex@example.com',phone:'07700 900123'},{id:'c2',name:'Jamie Wilson',email:'jamie@example.com',phone:'07700 900456'}],bookings:[{id:uid('bk'),serviceId:'brows',serviceName:'Brow shape & tint',price:25,duration:30,date,time:'10:00',customerId:'c1',name:'Alex Morgan',email:'alex@example.com',phone:'07700 900123',status:'confirmed',source:'Online',deposit:0},{id:uid('bk'),serviceId:'lashes',serviceName:'Lash lift',price:55,duration:60,date,time:'13:00',customerId:'c2',name:'Jamie Wilson',email:'jamie@example.com',phone:'07700 900456',status:'confirmed',source:'Manual',deposit:0}],emails:[],subscription:{status:'trialing',plan:'Essential',trialEnd:new Date(Date.now()+3*86400000).toISOString(),method:'Demo card •••• 4242'},payments:{stage:0,enabled:false,deposit:0,transactions:[]},usage:{sms:0,ai:0}};
}
function fresh(){const single=seedSalon('drink','Jova Demo Salon','jova-demo','#77504e');single.sms=[];return {version:1,active:'drink',salons:[single]};}
let state;
try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1||!Array.isArray(state.salons))state=fresh();}catch{state=fresh();}
const requestedSalon=new URL(location.href).searchParams.get('salon');
if(requestedSalon){const matched=state.salons.find(s=>s.slug===requestedSalon);if(matched)state.active=matched.id;}
let draft={},chat=[],lastBooking=null,calendarWeek=today(),search='',paymentMethod='Card';
const salon=()=>state.salons.find(s=>s.id===state.active)||state.salons[0];
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const go=route=>{if(location.hash==='#'+route)render();else location.hash=route;};
const route=()=>decodeURIComponent(location.hash.slice(1)||'plans');
const available=(date,serviceId,ignore=null)=>{
 const s=salon(),svc=s.services.find(x=>x.id===serviceId);
 if(!svc||!date||date<today()||!s.hours.days.includes(new Date(date+'T12:00:00').getDay()))return [];
 const out=[];
 for(let t=mins(s.hours.start);t+svc.duration+Number(s.buffer)<=mins(s.hours.end);t+=30){
  if(date===today()&&t<=new Date().getHours()*60+new Date().getMinutes()+Number(s.notice))continue;
  const conflict=s.bookings.some(b=>b.id!==ignore&&b.date===date&&b.status!=='cancelled'&&t<mins(b.time)+b.duration+Number(s.buffer)&&t+svc.duration+Number(s.buffer)>mins(b.time));
  if(!conflict)out.push(clock(t));
 }
 return out;
};
function nextDate(){for(let i=1;i<15;i++){const d=addDays(today(),i);if(salon().hours.days.includes(new Date(d+'T12:00:00').getDay()))return d;}return addDays(today(),1);}
function defaultDraft(){return {serviceId:salon().services[0]?.id,date:nextDate(),time:'',name:'',email:'',phone:'',method:'Card'};}
function ensureDraft(){if(!draft.serviceId||!salon().services.some(s=>s.id===draft.serviceId))draft=defaultDraft();}
function notify(kind,b){const s=salon();const title={confirmed:'Your booking is confirmed',cancelled:'Your booking has been cancelled',rescheduled:'Your booking has changed',reminder:'Your appointment reminder'}[kind];s.emails.unshift({id:uid('email'),kind,subject:`${s.name}: ${title.toLowerCase()}`,to:b.email,from:'Jova Bookings <bookings@jovamedia.com>',reply:s.email,at:new Date().toISOString(),booking:{...b},salonName:s.name,address:s.address,status:'Preview saved'});}
function bookingTable(list){if(!list.length)return '<div class="card empty">No appointments to show. Create one or try the customer booking flow.</div>';return `<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Service</th><th>When</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><b>${esc(b.name)}</b><span class="secondary">${esc(b.source)} booking</span></td><td>${esc(b.serviceName)}</td><td>${esc(humanDate(b.date))}<span class="secondary">${b.time} · ${b.duration} min</span></td><td>${money(b.price)}</td><td>${statusPill(b.status)}</td><td><button class="small" data-action="booking-details" data-id="${b.id}">View</button></td></tr>`).join('')}</tbody></table></div>`;}
function statusPill(status){return `<span class="pill ${status==='confirmed'||status==='active'?'green':status==='cancelled'?'red':status==='trialing'?'blue':''}">${esc(status==='trialing'?'Trial active':status[0].toUpperCase()+status.slice(1))}</span>`;}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function pubHeader(){return `<header class="topbar"><a class="brand" href="#plans">jova<em>book</em><small>BY JOVA MEDIA</small></a><nav><a href="#plans">Plans</a><a href="#book/service">Try customer booking</a><a href="#login">Owner login</a><a class="btn primary small" href="#signup">Get started</a></nav></header>`;}
const screenLinks=[['plans','Pricing & product','Essential offer'],['signup','Salon signup','Name, owner and booking address'],['setup','Salon setup','Hours, branding and services'],['checkout','Subscription checkout','Three-day trial and payment choice'],['login','Owner login','Simulated account access'],['dashboard','Owner overview','Setup checklist and appointments'],['calendar','Calendar','Week view and manual appointments'],['customers','Customers','Contact details and history'],['services','Services','Add, edit and remove treatments'],['team','Team preview','Future Standard team features'],['settings','Salon settings','Business, branding and availability'],['billing','Jova subscription','Trial, renewal and cancellation'],['payments','Payments & deposits','Salon payment account connection'],['onboarding','Stripe setup preview','Simulated embedded onboarding'],['notifications','Email & SMS','Confirmation and reminder previews'],['book/service','Customer: services','Choose a treatment'],['book/time','Customer: availability','Choose a date and free slot'],['book/details','Customer: details','Guest booking form'],['book/payment','Customer: payment','Simulated card and wallets'],['book/confirmation','Customer: confirmation','Saved booking and manage link'],['salon/home','Pro: salon website','Home, About and Contact'],['ai','Pro: AI booking preview','Scripted chat linked to availability']];
function screens(){modal('Essential screens',`<p>One test salon. Explore onboarding, login, booking and notifications. Payments and messages are previews.</p><div class="screen-grid">${screenLinks.filter(([r])=>!['team','salon/home','ai'].includes(r)).map(([r,t,d])=>`<a class="screen-link" href="#${r}" data-action="close-modal">${t}<small>${d}</small></a>`).join('')}</div>`,'large');}
function ownerShell(content,active){const s=salon();const nav=[['dashboard','◫','Overview'],['calendar','▦','Calendar'],['customers','♧','Customers'],['services','≡','Services'],['team','♙','Team preview'],['notifications','✉','Email & SMS'],['settings','⚙','Salon settings'],['payments','↔','Payments & deposits'],['billing','£','Jova subscription']];return `<div class="shell"><aside class="sidebar"><a class="brand" href="#plans">jova<em>book</em><small>OWNER WORKSPACE</small></a><div class="salon-switch"><label>PREVIEW SALON</label><strong>${esc(s.name)}</strong></div><nav class="side-nav">${nav.filter(([r])=>r!=='team').map(([r,i,t])=>`<a href="#${r}" class="${active===r?'active':''}"><span class="nav-icon">${i}</span>${t}</a>`).join('')}</nav><div class="bottom"><span class="pill blue">Essential · £20/month</span><p class="tiny section-space">Essential preview.<br>Data stays in this browser; no live account or payment connection.</p><a class="tiny" href="#plans">← Back to product</a></div></aside><section class="workspace"><header class="workspace-header"><div><strong>${esc(s.name)}</strong><div class="tiny muted">${esc(location.host)} · Essential preview</div></div><div class="row">${statusPill(s.subscription.status)}<a class="btn small" href="#book/service">View booking page ↗</a></div></header><main class="workspace-main">${content}</main></section></div>`;}
function plansPage(){return `${pubHeader()}<main class="container"><section class="hero"><div class="eyebrow">Booking software for independent salons</div><h1>Keep taking bookings.<br>Keep looking after your clients.</h1><p>A shared booking platform with your own salon address, a simple diary and email confirmations. Start with Essential.</p><div class="hero-actions"><a class="btn primary" href="#signup">Start a 3-day trial</a><a class="btn" href="#dashboard">Explore owner demo</a><button data-action="screens">See all screens</button></div><p class="demo-note">This localhost prototype demonstrates the whole journey. Trial, checkout, emails and Stripe setup are simulated.</p></section><div class="grid three">${[['Essential','20','Available first',['One bookable staff calendar','Customer and manual booking','Calendar and customer records','Email confirmations and reminders','Your own booking address']],['Standard','50','Planned',['Up to five bookable staff','Team permissions','Waitlist','Basic reporting','Everything in Essential']],['Pro','100','Planned',['Everything in Standard','Home, About and Contact website','AI booking text chat, once tested','Voice pilot with capped usage','Usage and payment settings']]].map(([n,p,b,f])=>`<article class="card"><div class="row between"><h2 style="margin:0">${n}</h2><span class="pill ${n==='Essential'?'green':'amber'}">${b}</span></div><div class="price">£${p}<small> / month</small></div><p class="tiny">${n==='Essential'?'Three-day trial. One solo professional.':'Future offer. Not available to purchase.'}</p><ul class="features">${f.map(x=>`<li>${x}</li>`).join('')}</ul>${n==='Essential'?'<a class="btn primary wide" href="#signup">Try Essential</a>':`<a class="btn wide" href="#${n==='Pro'?'salon/home':'team'}">Preview ${n}</a>`}</article>`).join('')}</div><div class="grid two section-space"><div class="card"><h3>Two payments. Two destinations.</h3><div class="key-value"><span>Salon pays £20/month</span><b>Jova Media</b></div><div class="key-value"><span>Customer pays a deposit</span><b>The salon</b></div><p class="tiny section-space">Treatment payments use the salon's connected account. Jova's software subscription is separate. Processing fees apply.</p></div><div class="card"><h3>What Essential doesn't need</h3><p>No AI model, SMS allowance or phone number. Email notifications use Jova's shared sending account. Salon-specific account separation and booking rules are part of the application.</p><a href="#costs">See the demo cost breakdown →</a></div></div>${footer()}</main>`;}
function footer(){return `<footer class="footer"><span>Powered by Jova Media · Essential preview</span><div class="row"><button class="quiet small" data-action="policy">Privacy information</button><button class="quiet small" data-action="cookies">Cookie settings</button></div></footer>`;}
function signupPage(){return `${pubHeader()}<main class="container narrow">${heading('Create your salon','Demo onboarding · Essential, £20/month after a three-day trial')}<div class="steps"><span class="step active">1 · Account</span><span class="step">2 · Salon setup</span><span class="step">3 · Trial checkout</span></div><form class="card" data-form="signup">${field('Salon name','name','','text','required placeholder="e.g. Drink Beauty" maxlength="70"')}${field('Your booking address','slug','','text','required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" minlength="3" maxlength="45" placeholder="drinkbeauty"')}<p class="tiny">Your address: <b id="slug-preview">yourname</b>.jovamedia.com · preview only</p><div class="grid two">${field('Owner name','owner','','text','required placeholder="Your name"')}${field('Owner email','email','','email','required placeholder="owner@example.com"')}</div><label class="check"><input type="checkbox" name="terms" required> I understand this is a preview. I will use example details, and no real subscription will be created.</label><div class="error" role="alert"></div><button class="btn primary wide">Create demo salon →</button></form></main>`;}
function setupPage(){const s=salon();return `${pubHeader()}<main class="container narrow">${heading('Set up your salon','Add the essentials before you start your trial.')}<div class="steps"><span class="step">1 · Account</span><span class="step active">2 · Salon setup</span><span class="step">3 · Trial checkout</span></div><form class="card" data-form="setup"><div class="notice">${esc(s.slug)}.jovamedia.com is an illustrative address. This preview does not create a live booking address.</div><div class="section-space">${field('Business address','address',s.address,'text','required')}${field('Contact phone','phone',s.phone,'tel','required')}</div><div class="grid two">${field('Opening time','start',s.hours.start,'time','required')}${field('Closing time','end',s.hours.end,'time','required')}</div><label class="field">Open days</label>${dayChecks(s.hours.days)}<div class="grid two section-space">${field('Brand colour','color',s.color,'color')}${field('First service name','service',s.services[0]?.name||'Consultation','text','required')}</div><div class="grid two">${field('Service price (£)','price',s.services[0]?.price||25,'number','min="0" max="2000" step="0.01" required')}${field('Duration (minutes)','duration',s.services[0]?.duration||30,'number','min="15" max="240" step="15" required')}</div><div class="error" role="alert"></div><div class="form-footer"><a href="#dashboard">Skip to dashboard</a><button class="btn primary">Save & continue →</button></div></form></main>`;}
function dayChecks(selected){return `<div class="toggle-grid">${days.map((d,i)=>`<label class="day-check"><input type="checkbox" name="days" value="${i}" ${selected.includes(i)?'checked':''}>${d}</label>`).join('')}</div>`;}
function loginPage(){return `${pubHeader()}<main class="container"><div class="card login-card"><div class="eyebrow">Owner access</div><h1>Welcome back.</h1><p>Choose a demo salon to enter its separate workspace. This prototype does not implement real authentication.</p><form data-form="login"><label class="field">Demo salon<select name="salon">${state.salons.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><button class="btn primary wide">Enter demo workspace</button></form><hr class="divider"><a href="#signup">Create another demo salon →</a></div></main>`;}
function checkoutPage(){const s=salon();return `${pubHeader()}<main class="container narrow">${heading('Start your Essential trial','Simulated Stripe subscription checkout')}<div class="steps"><span class="step">1 · Account</span><span class="step">2 · Salon setup</span><span class="step active">3 · Trial checkout</span></div><div class="card"><div class="row between"><h2>${esc(s.name)}</h2><span class="pill blue">Essential</span></div><div class="key-value"><span>Due today</span><b>£0.00</b></div><div class="key-value"><span>Then, after three days</span><b>£20.00 / month</b></div><div class="key-value"><span>First charge in this simulation</span><b>${esc(humanDate(addDays(today(),3)))}</b></div><div class="section-space"><label class="field">Choose a demo payment method</label>${wallets(paymentMethod,'subscription-method')}</div><div class="skeleton-bank section-space"><b>${paymentMethod==='Card'?'Demo card •••• 4242':paymentMethod+' demo wallet'}</b><p class="tiny" style="margin:8px 0 0">No card numbers or real wallet credentials are collected. No charge will be made.</p></div><form data-form="checkout"><label class="check"><input type="checkbox" required> Activate a simulated three-day trial, followed by £20/month. I can cancel the demo subscription in settings.</label><button class="btn primary wide">Activate demo trial — £0 today</button></form><p class="demo-note section-space">In production, Stripe-hosted payment entry and verified payment events control subscription status. This screen simulates that flow.</p></div></main>`;}
function wallets(selected,action){return `<div class="wallets">${['Card','Apple Pay','Google Pay'].map(m=>`<button type="button" class="${selected===m?'selected':''}" data-action="${action}" data-value="${m}">${m}</button>`).join('')}</div>`;}
function overview(){const s=salon(),up=s.bookings.filter(b=>b.date>=today()&&b.status==='confirmed').sort(sortBookings);const paid=s.payments.transactions.reduce((a,t)=>a+t.net,0);return heading('Your salon, at a glance','Manage the diary or walk through a customer booking.',`<button class="btn primary" data-action="new-booking">+ New appointment</button>`)+`<div class="stats"><div class="stat"><span>Upcoming appointments</span><b>${up.length}</b><small>Confirmed in your diary</small></div><div class="stat"><span>Appointment value</span><b>${money(up.reduce((a,b)=>a+b.price,0))}</b><small>Scheduled value, not collected cash</small></div><div class="stat"><span>Customers</span><b>${s.customers.length}</b><small>Only this salon's records</small></div><div class="stat"><span>Demo payments received</span><b>${money(paid)}</b><small>Net of illustrative processing fees</small></div></div><div class="grid two"><div class="card"><h3>Launch checklist</h3>${[['✓','Salon account created',s.name,'settings'],['✓','Customer booking page',location.host+'/#book/service','book/service'],[s.services.length?'✓':'2','Services and availability',s.services.length+' services · 1 bookable calendar','services'],[s.subscription.status==='trialing'?'✓':'3','Subscription setup',s.subscription.status==='trialing'?'Three-day trial active':'Review trial and payment status','billing'],[s.payments.enabled?'✓':'4','Online deposit payments',s.payments.enabled?'Demo connected account ready':'Optional; simulated setup available','payments']].map(([n,t,d,r])=>`<div class="task"><span class="badge-circle">${n}</span><div class="grow"><b class="tiny">${t}</b><small>${esc(d)}</small></div><a href="#${r}">Open →</a></div>`).join('')}</div><div class="card"><h3>Your customer booking link</h3><p class="mono tiny" style="overflow-wrap:anywhere">${esc(location.origin)}/#book/service</p><p class="tiny">Use this hosted preview link to explore the customer booking journey. Records are saved in this browser only.</p><div class="row"><a class="btn primary small" href="#book/service">Try a customer booking</a><button class="small" data-action="copy-link">Copy preview link</button></div><hr class="divider"><h3>Follow a whole journey</h3><p class="tiny">Make a booking, return to the calendar, inspect the confirmation email, then reschedule or cancel it. All screens use the same saved demo records.</p><button class="small" data-action="screens">Browse all screens</button></div></div><div class="section-space"><div class="row between"><h2>Upcoming appointments</h2><a href="#calendar">Open calendar →</a></div>${bookingTable(up.slice(0,6))}</div>`;}
function sortBookings(a,b){return (a.date+a.time).localeCompare(b.date+b.time);}
function calendar(){const s=salon(),d=new Date(calendarWeek+'T12:00:00'),day=d.getDay();const monday=addDays(calendarWeek,-((day+6)%7));const week=Array.from({length:7},(_,i)=>addDays(monday,i));return heading('Calendar','One bookable staff calendar on Essential.',`<button class="btn primary" data-action="new-booking">+ New appointment</button>`)+`<div class="toolbar"><div class="row"><button class="small" data-action="calendar-prev">← Previous</button><button class="small" data-action="calendar-now">This week</button><button class="small" data-action="calendar-next">Next →</button></div><b>${humanDate(week[0])} – ${humanDate(week[6])}</b><span class="pill">${esc(s.staff[0].name)}</span></div><div class="calendar-scroll"><div class="calendar">${week.map(date=>{const bookings=s.bookings.filter(b=>b.date===date).sort(sortBookings);return `<section class="day ${date===today()?'today':''}"><div class="day-head">${days[new Date(date+'T12:00:00').getDay()]}<b>${new Date(date+'T12:00:00').getDate()}</b></div>${bookings.map(b=>`<button class="event ${b.status}" data-action="booking-details" data-id="${b.id}">${b.time} · ${b.duration} min<strong>${esc(b.name)}</strong><small>${esc(b.serviceName)}</small><small>${money(b.price)} · ${esc(b.status)}</small></button>`).join('')||'<span class="blank-day">No appointments</span>'}</section>`;}).join('')}</div></div><div class="section-space"><h2>All appointments</h2>${bookingTable([...s.bookings].sort(sortBookings))}</div>`;}
function customers(){const s=salon(),list=s.customers.filter(c=>(c.name+' '+c.email).toLowerCase().includes(search.toLowerCase()));return heading('Customers','Contacts and appointment history for this salon.')+`<div class="toolbar"><input type="search" aria-label="Search customers" id="customer-search" placeholder="Search name or email" value="${esc(search)}"><button data-action="export">Export salon data</button></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Appointments</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.email)}</td><td>${esc(c.phone)}</td><td>${s.bookings.filter(b=>b.customerId===c.id).length}</td><td><button class="small" data-action="customer" data-id="${c.id}">View history</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching customers.</td></tr>'}</tbody></table></div>`;}
function services(){const s=salon();return heading('Services','Prices and durations appear in your public booking flow.',`<button class="btn primary" data-action="add-service">+ Add service</button>`)+`<div class="table-wrap"><table><thead><tr><th>Service</th><th>Duration</th><th>Price</th><th></th></tr></thead><tbody>${s.services.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.duration} min</td><td>${money(x.price)}</td><td><button class="small" data-action="edit-service" data-id="${x.id}">Edit</button> <button class="small danger" data-action="remove-service" data-id="${x.id}">Remove</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Add your first service to accept bookings.</td></tr>'}</tbody></table></div><div class="notice section-space">Changing a current price does not rewrite the price saved against an existing appointment.</div>`;}
function team(){const s=salon();return heading('Team','Preview of the future Standard plan.')+`<div class="notice amber">Essential includes one bookable calendar. Standard (£50/month) is planned for up to five. This local preview does not upgrade your subscription.</div><div class="card section-space"><div class="row between"><div><h3>${esc(s.staff[0].name)}</h3><p class="tiny" style="margin:0">Owner · Bookable · All services</p></div><span class="pill green">Active</span></div><hr class="divider"><button data-action="team-invite">Preview staff invitation</button><p class="tiny section-space">Team permissions, invitations and additional calendars will be built after Essential is validated.</p></div>`;}
function settings(){const s=salon();return heading('Salon settings','Update the details used by your booking page and emails.')+`<form data-form="settings" class="stack"><div class="grid two"><section class="card"><h2>Business & branding</h2>${field('Salon name','name',s.name,'text','required maxlength="70"')}${field('Contact email / email reply address','email',s.email,'email','required')}${field('Contact phone','phone',s.phone,'tel')}${field('Address','address',s.address,'text','required')}${field('Brand colour','color',s.color,'color')}<label class="field">About your salon<textarea name="about" maxlength="700">${esc(s.about)}</textarea></label><div class="key-value"><span>Booking address</span><b>${esc(s.slug)}.jovamedia.com</b></div><p class="tiny section-space">Address changes are deliberately excluded from this demo to keep existing customer links stable.</p></section><section class="card"><h2>Booking rules</h2><div class="grid two">${field('Opening time','start',s.hours.start,'time','required')}${field('Closing time','end',s.hours.end,'time','required')}</div><label class="field">Open days</label>${dayChecks(s.hours.days)}<div class="section-space">${field('Buffer after appointments (minutes)','buffer',s.buffer,'number','min="0" max="120" step="5" required')}${field('Minimum same-day notice (minutes)','notice',s.notice,'number','min="0" max="480" step="15" required')}</div><p class="tiny">The demo checks these rules when showing slots and again when saving a booking. Existing appointments retain their saved time.</p><hr class="divider"><h3>Export & privacy</h3><p class="tiny">Demo data stays in this browser. Export it or reset the demonstration using the top bar.</p><button type="button" data-action="export">Export this salon's data</button></section></div><div class="error" role="alert"></div><button class="btn primary">Save settings</button></form>`;}
function billing(){const s=salon(),sub=s.subscription;const end=new Date(sub.trialEnd).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});return heading('Jova subscription','This pays for JovaBook software. It is separate from your customers’ payments.')+`<div class="grid two"><section class="card"><div class="row between"><h2>Essential</h2>${statusPill(sub.status)}</div><div class="price">£20<small> / month</small></div><div class="key-value"><span>Plan includes</span><b>1 bookable staff calendar</b></div><div class="key-value"><span>Trial ends</span><b>${esc(end)}</b></div><div class="key-value"><span>Payment method</span><b>${esc(sub.method||'Not added')}</b></div><div class="money-flow"><span>Your salon</span>→<span>Jova's Stripe account</span>→<span>Jova Media</span></div><div class="row section-space">${sub.status==='cancelled'?'<button class="btn primary" data-action="restart-trial">Restart demo trial</button>':'<button data-action="cancel-subscription" class="danger">Cancel subscription</button>'}<button data-action="portal">Manage payment method</button></div></section><section class="card"><h2>Test subscription states</h2><p class="tiny">These controls simulate payment events locally. They do not change a Stripe account or charge a card.</p><div class="row"><button data-action="billing-state" data-value="active">Simulate first £20 payment</button><button data-action="billing-state" data-value="past_due">Simulate failed renewal</button></div><hr class="divider"><a class="btn small" href="#plans">Back to Essential</a></section></div><div class="notice ${sub.status==='past_due'?'amber':''} section-space">${sub.status==='past_due'?'Demo payment failed. The owner needs a clear way to update payment details. Existing appointment records are retained.':sub.status==='cancelled'?'Demo renewal cancelled. No future subscription payment is scheduled. Saved appointments remain available in this prototype.':'Trial and renewal behaviour is simulated. Your dashboard shows the stored status; no actual payments are scheduled.'}</div>`;}
function payments(){const s=salon(),p=s.payments;return heading('Payments & deposits','Customer treatment money goes to your salon account, separately from Jova’s subscription.')+`<div class="grid two"><section class="card"><div class="row between"><h2>Online payments</h2><span class="pill ${p.enabled?'green':'amber'}">${p.enabled?'Demo enabled':'Not connected'}</span></div><p>Connect a salon payment account and set where your treatment money goes.</p><div class="money-flow"><span>Customer</span>→<span>Your connected Stripe balance</span>→<span>Your bank</span></div>${p.enabled?`<div class="skeleton-bank"><b>Demo bank account •••• 6789</b><p class="tiny" style="margin:7px 0 0">Account: ${esc(s.name)} · Connection simulated</p></div><form data-form="deposit" class="section-space">${field('Optional deposit per appointment (£)','amount',p.deposit,'number','min="0" max="200" step="0.01" required')}<p class="tiny">Set 0 for no deposit. A deposit is capped at the selected service price.</p><button class="btn primary">Save deposit setting</button></form>`:'<a class="btn primary" href="#onboarding">Set up booking payments →</a>'}<p class="demo-note section-space">This is an optional future-payment preview. No Stripe account is created, no bank details are collected, and no money moves.</p></section><section class="card"><h2>Demo payment totals</h2><div class="key-value"><span>Customer deposits collected</span><b>${money(p.transactions.reduce((a,t)=>a+t.amount,0))}</b></div><div class="key-value"><span>Illustrative processing fees</span><b>${money(p.transactions.reduce((a,t)=>a+t.fee,0))}</b></div><div class="key-value"><span>Net for the salon</span><b>${money(p.transactions.reduce((a,t)=>a+t.net,0))}</b></div><div class="key-value"><span>Jova treatment commission</span><b>£0.00</b></div><p class="tiny section-space">Fee illustration: 1.5% + 20p for a standard UK card, not a quote for every card or account. Wallets use the applicable card processing fee.</p><a class="btn small" href="#book/service">Try a customer deposit</a></section></div><div class="section-space"><h2>Transactions</h2><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Method</th><th>Deposit</th><th>Fee illustration</th><th>Salon net</th><th>Status</th></tr></thead><tbody>${p.transactions.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.method)}</td><td>${money(t.amount)}</td><td>${money(t.fee)}</td><td>${money(t.net)}</td><td><span class="pill green">Simulated payment</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No simulated treatment payments yet.</td></tr>'}</tbody></table></div></div>`;}
function onboarding(){const s=salon(),step=s.payments.stage;return heading('Set up booking payments','Preview of Stripe embedded onboarding inside the salon dashboard.')+`<div class="notice amber">Demonstration only. This is a Jova-built mock-up, not Stripe's actual embedded component. Use example information; do not enter real identity or bank details.</div><div class="grid two section-space"><div class="onboarding"><div class="onboarding-label"><b>Payment account setup</b><span class="pill">Simulated Stripe flow</span></div><div class="steps">${['Business','Bank account','Review'].map((n,i)=>`<span class="step ${i===step?'active':''}">${i+1} · ${n}</span>`).join('')}</div>${step===0?`<h2>About your business</h2><form data-form="onboard-business">${field('Business name','name',s.name,'text','required')}<label class="field">Business type<select name="type"><option>Sole trader</option><option>Limited company</option></select></label><div class="key-value"><span>Country</span><b>United Kingdom</b></div><div class="form-footer"><a href="#payments">Back</a><button class="btn primary">Continue →</button></div></form>`:step===1?`<h2>Where should payouts go?</h2><p class="tiny">In the real Stripe component, the owner supplies bank details securely to Stripe. Here we use a fixed example.</p><div class="skeleton-bank"><b>Demo Business Bank</b><div class="key-value"><span>Account holder</span><b>${esc(s.name)}</b></div><div class="key-value"><span>Account ending</span><b>6789</b></div></div><div class="form-footer"><button data-action="onboard-back">← Back</button><button class="btn primary" data-action="onboard-next">Use example bank →</button></div>`:`<h2>Ready to enable payments?</h2><div class="key-value"><span>Business</span><b>${esc(s.name)}</b></div><div class="key-value"><span>Bank</span><b>Demo account •••• 6789</b></div><div class="key-value"><span>Verification</span><b>Simulated successful</b></div><p class="tiny section-space">Real verification can require identity documents and further checks. This demonstration approves example data only.</p><div class="form-footer"><button data-action="onboard-back">← Back</button><button class="btn primary" data-action="onboard-complete">Enable demo payments</button></div>`}</div><div class="card"><h3>What this connects</h3><p>Your customers' payments to your salon's payment account and bank.</p><h3>What stays separate</h3><p>Your £20/month Jova software subscription. This setup does not change your plan.</p><h3>What we build for the real product</h3><p class="tiny">Create the connected account on the server, embed Stripe's actual component, verify its readiness, and map the account to the correct salon before allowing payment checkout.</p></div></div>`;}
function notifications(){const s=salon(),count=state.salons.reduce((n,x)=>n+x.emails.length,0);return heading('Email & SMS','Preview the messages generated by your bookings.',`<button data-action="reminders">Simulate due reminders</button>`)+`<div class="grid three"><div class="stat"><span>This salon's demo emails</span><b>${s.emails.length}</b></div><div class="stat"><span>Across all demo salons</span><b>${count}</b><small>Illustrates one shared sending account</small></div><div class="stat"><span>Resend free allowance reference</span><b>100 / day</b><small>3,000 per month across the account</small></div></div><div class="notice section-space">Messages below are saved locally, not delivered. The real sender can be Jova Bookings, with the salon details inside and its email as Reply-To.</div><div class="table-wrap section-space"><table><thead><tr><th>Subject</th><th>To</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>${s.emails.map(e=>`<tr><td>${esc(e.subject)}</td><td>${esc(e.to)}</td><td>${esc(e.kind)}</td><td><span class="pill">${e.status}</span></td><td><button class="small" data-action="email" data-id="${e.id}">Preview email</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Create or change a booking to generate a demo email.</td></tr>'}</tbody></table></div>`;}
function bookHeader(){const s=salon();return `<header class="book-header"><div class="book-header-inner"><a class="row" href="#book/service" style="color:inherit"><span class="avatar">${esc(s.initials)}</span><span><b>${esc(s.name)}</b><span class="secondary tiny muted" style="display:block;margin-top:4px">${esc(s.address)}</span></span></a><a class="tiny" href="#dashboard">Owner dashboard ↗</a></div></header>`;}
function bookSummary(){const s=salon(),svc=s.services.find(x=>x.id===draft.serviceId);return `<aside class="card"><h3>Your appointment</h3><div class="key-value"><span>Service</span><b>${esc(svc?.name||'Choose a service')}</b></div><div class="key-value"><span>Professional</span><b>${esc(s.staff[0].name)}</b></div><div class="key-value"><span>Date</span><b>${draft.date?humanDate(draft.date):'—'}</b></div><div class="key-value"><span>Time</span><b>${draft.time||'Choose a time'}</b></div><div class="key-value"><span>Total</span><b>${svc?money(svc.price):'—'}</b></div><p class="tiny section-space">Times shown in Europe/London. Preview only; data stays in this browser.</p></aside>`;}
function bookPage(step){ensureDraft();const s=salon(),svc=s.services.find(x=>x.id===draft.serviceId);const steps=['service','time','details','payment','confirmation'];let body='';if(!steps.includes(step))step='service';
 if(step==='service')body=`<h1>Book an appointment</h1><p>Choose a treatment to see availability.</p>${s.services.map(x=>`<button class="select-card ${draft.serviceId===x.id?'chosen':''}" data-action="select-service" data-id="${x.id}"><span><strong>${esc(x.name)}</strong><small>${x.duration} minutes · ${esc(s.staff[0].name)}</small></span><span class="money">${money(x.price)} →</span></button>`).join('')||'<div class="empty">This salon has no bookable services yet.</div>'}`;
 if(step==='time')body=`<h1>Choose a time</h1><p>${esc(svc?.name||'Service')} · ${svc?.duration||0} minutes</p><label class="field">Appointment date<input type="date" min="${today()}" value="${draft.date}" data-change="booking-date"></label><div class="slots">${available(draft.date,draft.serviceId).map(t=>`<button class="${draft.time===t?'chosen':''}" data-action="select-time" data-time="${t}">${t}</button>`).join('')||'<p class="muted">No slots available. Try another date or check the salon’s opening days.</p>'}</div><div class="form-footer"><a href="#book/service">← Services</a><a class="btn primary" href="#book/details">Continue →</a></div>`;
 if(step==='details'){if(!draft.time)draft.time=available(draft.date,draft.serviceId)[0]||'';body=`<h1>Your details</h1><p>Book as a guest. Use example details for this demo.</p>${!draft.time?'<div class="notice amber">Choose an available date and time first.</div>':''}<form data-form="customer-details">${field('Full name','name',draft.name,'text','required autocomplete="off" placeholder="e.g. Taylor Demo"')}${field('Email for confirmation','email',draft.email,'email','required autocomplete="off" placeholder="taylor@example.com"')}${field('Phone (optional)','phone',draft.phone,'tel','autocomplete="off" placeholder="07700 900000"')}<label class="check"><input type="checkbox" required> I understand this is a demo booking. No real appointment or payment will be created.</label><div class="error" role="alert"></div><div class="form-footer"><a href="#book/time">← Time</a><button class="btn primary" ${!draft.time?'disabled':''}>Review booking →</button></div></form>`;}
 if(step==='payment'){if(!draft.time)draft.time=available(draft.date,draft.serviceId)[0]||'';const amount=s.payments.enabled?Math.min(s.payments.deposit,svc?.price||0):0;body=`<h1>${amount?'Pay your deposit':'Review your booking'}</h1><p>${draft.name?`Booking for ${esc(draft.name)}.`:'Screen preview. Enter customer details before confirming.'}</p><div class="key-value"><span>Appointment total</span><b>${money(svc?.price)}</b></div><div class="key-value"><span>Due now</span><b>${money(amount)}</b></div><div class="key-value"><span>Pay at the salon</span><b>${money((svc?.price||0)-amount)}</b></div>${amount?`<div class="section-space"><label class="field">Demo payment method</label>${wallets(draft.method||'Card','customer-method')}</div><div class="skeleton-bank section-space"><b>Simulated ${esc(draft.method||'Card')} payment</b><p class="tiny" style="margin:8px 0 0">No real wallet or card details requested. The demo deposit is recorded for ${esc(s.name)}.</p></div>`:'<div class="notice section-space">No deposit required. Pay for your treatment at the salon. No payment details collected.</div>'}<p class="demo-note section-space">${amount?'In production, Stripe checkout processes the deposit on the salon’s connected account.':'You can preview optional deposits by enabling demo payments in the owner dashboard.'}</p><div class="error" id="booking-error" role="alert"></div><div class="form-footer"><a href="#book/details">← Details</a><button class="btn primary" data-action="confirm-booking">${amount?'Pay '+money(amount)+' & book (demo)':'Confirm demo booking'}</button></div>`;}
 if(step==='confirmation'){const b=s.bookings.find(x=>x.id===lastBooking)||s.bookings.find(x=>x.status==='confirmed');body=b?confirmation(b):'<h1>No booking yet</h1><p>Complete the customer flow to see a saved confirmation.</p><a class="btn primary" href="#book/service">Start a booking</a>';}
 return `${bookHeader()}<main class="container" style="max-width:970px"><div class="steps">${['Service','Date & time','Your details','Review / pay','Confirmed'].map((x,i)=>`<span class="step ${steps.indexOf(step)===i?'active':''}">${i+1} · ${x}</span>`).join('')}</div><div class="booking-layout"><section class="card">${body}</section>${step==='confirmation'?'':bookSummary()}</div>${footer()}</main>`;
}
function confirmation(b){return `<div class="center"><div class="success-icon">✓</div><h1>Demo booking saved.</h1><p>This appointment and its confirmation preview are saved in this browser. No email was sent.</p></div><div class="key-value"><span>Booking reference</span><b class="mono">${esc(b.id)}</b></div><div class="key-value"><span>Service</span><b>${esc(b.serviceName)}</b></div><div class="key-value"><span>When</span><b>${humanDate(b.date)} · ${b.time}</b></div><div class="key-value"><span>Total / demo deposit</span><b>${money(b.price)} / ${money(b.deposit)}</b></div><div class="row section-space"><a class="btn primary" href="#manage/${b.id}">Manage appointment</a><a class="btn" href="#calendar">View owner calendar</a><a class="btn" href="#notifications">View email</a></div>`;}
function manage(id){const b=salon().bookings.find(x=>x.id===id);if(!b)return `${bookHeader()}<main class="container narrow"><div class="card"><h1>Appointment not found</h1><p>This reference is not available for the selected demo salon.</p><a href="#book/service">Back to booking</a></div></main>`;return `${bookHeader()}<main class="container narrow"><section class="card"><div class="row between"><h1>Your appointment</h1>${statusPill(b.status)}</div><p>${esc(b.name)} · Reference ${esc(b.id)}</p><div class="key-value"><span>Service</span><b>${esc(b.serviceName)}</b></div><div class="key-value"><span>When</span><b>${humanDate(b.date)} · ${b.time}</b></div><div class="key-value"><span>Price</span><b>${money(b.price)}</b></div><div class="row section-space">${b.status==='confirmed'?`<button class="btn primary" data-action="reschedule" data-id="${b.id}">Reschedule</button><button class="danger" data-action="cancel-booking" data-id="${b.id}">Cancel appointment</button>`:''}<a class="btn" href="#book/service">Book another</a></div><p class="demo-note section-space">The production version requires a secure appointment-management token. This preview uses a visible demo reference. A cancellation does not issue a real refund.</p></section>${footer()}</main>`;}
function salonPreview(tab){const s=salon();let body;if(tab==='about')body=`<div class="card"><h1>About ${esc(s.name)}</h1><p>${esc(s.about)}</p><a class="btn salon-btn" href="#book/service">Book now</a></div>`;else if(tab==='contact')body=`<div class="grid two"><section class="card"><h1>Find us</h1><p>${esc(s.address)}</p><div class="key-value"><span>Phone</span><b>${esc(s.phone)}</b></div><div class="key-value"><span>Email</span><b>${esc(s.email)}</b></div><div class="key-value"><span>Open</span><b>${s.hours.days.map(d=>days[d]).join(', ')}<br>${s.hours.start}–${s.hours.end}</b></div></section><section class="card inset center"><h2>Map location</h2><p>${esc(s.address)}</p><p class="tiny">Map placeholder. No third-party map or tracking loads in this local demo.</p><button data-action="map-preview">Preview map settings</button></section></div>`;else body=`<div class="preview-hero"><div class="eyebrow" style="color:var(--salon)">Your local independent salon</div><h1>Time for yourself.<br>Care from ${esc(s.name)}.</h1><p>${esc(s.about)}</p><a class="btn salon-btn" href="#book/service">Book an appointment →</a></div><div class="grid two"><div class="card"><h2>A simple booking experience</h2><p>Choose your treatment and a time that suits you. We'll send your appointment details by email.</p><a href="#book/service">View services & availability →</a></div><div class="card"><h2>Visit the salon</h2><p>${esc(s.address)}<br>${esc(s.phone)}</p><a href="#salon/contact">Opening times & contact →</a></div></div>`;return `<div class="notice amber" style="border-radius:0;border-width:0 0 1px">PRO WEBSITE PREVIEW · Future £100 plan. Your current Essential subscription is unchanged.</div><header class="topbar"><a class="row" href="#salon/home" style="color:var(--ink)"><span class="avatar">${esc(s.initials)}</span><b>${esc(s.name)}</b></a><nav><a href="#salon/home">Home</a><a href="#salon/about">About</a><a href="#salon/contact">Contact</a><a class="btn salon-btn" href="#book/service">Book now</a></nav></header><main class="container" style="max-width:970px">${body}<footer class="footer"><span>${esc(s.phone)} · ${esc(s.email)}<br>Powered by Jova Media</span><div class="row"><button class="quiet small" data-action="policy">Privacy</button><button class="quiet small" data-action="cookies">Cookie settings</button><a href="#dashboard">Owner dashboard</a></div></footer></main>`;}
function aiPage(){return heading('AI booking preview','A scripted interaction to demonstrate the future flow. No AI API or voice service is connected.')+`<div class="notice amber">PRO CONCEPT · This demo uses local rules, not a language model. It can show real demo availability and send you into the booking flow. It never charges API credits or books without your confirmation.</div><div class="grid two section-space"><section class="card"><h2>${esc(salon().name)} booking assistant</h2><div class="chat" id="chat-log">${(chat.length?chat:[{role:'assistant',text:'Hi! Tell me which treatment you want, or ask to see available appointments.'}]).map(x=>`<div class="bubble ${x.role==='user'?'user':''}">${esc(x.text)}</div>`).join('')}</div><form data-form="chat"><div class="row"><input style="flex:1;min-width:160px;padding:12px;border:1px solid var(--line);border-radius:6px" name="message" aria-label="Message the demo booking assistant" placeholder="e.g. I'd like a lash lift" required><button class="btn primary">Send</button></div></form><div class="row section-space">${salon().services.map(x=>`<button class="small" data-action="chat-prompt" data-value="${esc(x.name)}">${esc(x.name)}</button>`).join('')}</div><div class="row section-space"><a class="btn" href="#book/time">Continue to available times</a></div></section><section class="card"><h3>How production AI would work</h3><div class="task"><span class="badge-circle">1</span><span>Understand the requested service.</span></div><div class="task"><span class="badge-circle">2</span><span>Ask the salon's booking API for real slots.</span></div><div class="task"><span class="badge-circle">3</span><span>Ask the customer to confirm the details.</span></div><div class="task"><span class="badge-circle">4</span><span>Create the appointment through the booking engine.</span></div><hr class="divider"><h3>Voice is a separate pilot</h3><p class="tiny">Phone number, missed-call forwarding, per-minute costs and fallback need their own integration. No live calls are available here.</p></section></div>`;}
function costs(){return `${pubHeader()}<main class="container narrow">${heading('What costs what','Planning reference, checked 29 October 2026. Vendor prices are in US dollars.')}<div class="card"><div class="key-value"><span>Vercel Pro hosting</span><b>From US$20/month</b></div><div class="key-value"><span>Supabase Pro database</span><b>From US$25/month</b></div><div class="key-value"><span>Resend email (within free limits)</span><b>$0 · 100/day, 3,000/month</b></div><div class="key-value"><span>Shared example base</span><b>US$45/month</b></div><div class="key-value"><span>With Resend Pro ($20)</span><b>US$65/month</b></div><hr class="divider"><p class="tiny">These totals exclude taxes, extra usage, currency conversion, support and domain renewal. One shared application and database can serve multiple salons securely once account isolation is implemented.</p><div class="key-value"><span>Illustrative fees on a £20 subscription</span><b>£0.64</b></div><p class="tiny section-space">Assumes standard UK card processing at 1.5% + 20p and Stripe Billing at 0.7%. Treatment deposits have a separate payment flow and account configuration.</p><div class="notice">SMS reminders require a connected provider and may incur costs. AI chat and voice are outside this preview.</div></div>${footer()}</main>`;}
function essentialLanding(){return `${pubHeader()}<main class="container narrow">${heading('One salon. One simple booking system.','Essential preview · £20/month after a three-day trial.')}<div class="card"><span class="pill green">Essential only</span><div class="price">£20<small> / month</small></div><p>One bookable calendar, online and manual appointments, customer records, a booking page and email confirmation.</p><div class="notice">Notification flow: booking confirmed → email confirmation immediately → SMS reminder the day before the appointment. Both are previews until delivery is connected.</div><div class="hero-actions"><a class="btn primary" href="#signup">Try salon onboarding</a><a class="btn" href="#login">See owner login</a><a class="btn" href="#book/service">Customer booking page</a></div><button data-action="screens">Explore Essential screens</button><hr class="divider"><p class="demo-note">One example salon. This preview stores example data in the browser; login, billing and message delivery are demonstrations until the backend and sender configuration are completed.</p></div>${footer()}</main>`;}
function essentialLogin(){return `${pubHeader()}<main class="container narrow"><div class="card"><div class="eyebrow">Salon owner access</div><h1>Sign in to your salon</h1><p>Preview the proposed email sign-in journey. No authentication or email delivery is connected.</p><form data-form="login-preview">${field('Owner email','email',salon().email,'email','required placeholder="owner@example.com"')}<button class="btn primary wide">Preview sign-in email</button></form><div class="notice amber section-space">Email delivery is not connected in this preview. The next screen demonstrates the verification link; nothing is sent to the entered address.</div><a class="btn small section-space" href="#dashboard">Explore owner dashboard</a></div></main>`;}
function essentialNotifications(){const s=salon();const upcoming=s.bookings.filter(b=>b.status==='confirmed'&&b.phone);return heading('Email confirmations & SMS reminders','One immediate email, followed by a text reminder the day before.')+`<div class="grid two"><div class="card"><h2>Email confirmation</h2><p>The proposed confirmation includes the salon name, service, date, time, address and management link, with replies directed to the salon.</p><span class="pill amber">Preview only · no sender connected</span><div class="key-value"><span>Shared Resend free allowance</span><b>100/day · 3,000/month</b></div><p class="tiny section-space">Existing Jova emails also use this allowance.</p></div><div class="card"><h2>Day-before SMS</h2><p>The proposed reminder is sent to the customer's mobile the day before. This preview has no scheduler or delivery connection.</p><span class="pill amber">No SMS provider connected</span><div class="key-value"><span>TextBee free software tier</span><b>50/day · 300/month</b></div><p class="tiny section-space">Needs an Android phone and suitable SIM plan. Carrier service is separate. No real SMS is sent from this preview.</p></div></div><div class="section-space"><h2>SMS reminder queue</h2><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Mobile</th><th>Reminder due</th><th>Status</th><th></th></tr></thead><tbody>${upcoming.map(b=>`<tr><td>${esc(b.name)}</td><td>${esc(b.phone)}</td><td>${humanDate(addDays(b.date,-1))} · ${b.time}<span class="secondary">Day before · Europe/London</span></td><td><span class="pill amber">Awaiting sender setup</span></td><td><button class="small" data-action="sms-preview" data-id="${b.id}">Preview SMS</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Book an appointment with an example mobile number to see its reminder here.</td></tr>'}</tbody></table></div></div><div class="section-space"><h2>Email activity</h2><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Recipient</th><th>Status</th><th></th></tr></thead><tbody>${s.emails.map(e=>`<tr><td>${esc(e.subject)}</td><td>${esc(e.to)}</td><td>Preview saved, not delivered</td><td><button class="small" data-action="email" data-id="${e.id}">Preview email</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">A booking generates an immediate confirmation preview.</td></tr>'}</tbody></table></div></div>`;}
function render(){const r=route(),parts=r.split('/');const s=salon();document.documentElement.style.setProperty('--salon',s.color);let html;
 const admin={dashboard:overview,calendar,customers,services,settings,billing,payments,onboarding,notifications:essentialNotifications};
 if(admin[parts[0]])html=ownerShell(admin[parts[0]](),parts[0]);
 else if(parts[0]==='plans')html=essentialLanding();else if(parts[0]==='signup')html=signupPage();else if(parts[0]==='setup')html=setupPage();else if(parts[0]==='login')html=essentialLogin();else if(parts[0]==='checkout')html=checkoutPage();else if(parts[0]==='book')html=bookPage(parts[1]||'service');else if(parts[0]==='manage')html=manage(parts[1]);else if(parts[0]==='costs')html=costs();else html=`${pubHeader()}<main class="container"><div class="card"><h1>This feature is on hold</h1><p>We are focusing on Essential first.</p><a href="#plans">Back to Essential</a></div></main>`;
 $('#app').innerHTML=html;document.title=`${({'plans':'Product & plans','book':'Customer booking','manage':'Manage appointment','salon':'Pro website preview'}[parts[0]]||parts[0][0].toUpperCase()+parts[0].slice(1))} · JovaBook Essential preview`;
 if($('#chat-log'))$('#chat-log').scrollTop=$('#chat-log').scrollHeight;
}
function modal(title,content,size=''){closeModal();$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${size}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button aria-label="Close dialog" data-action="close-modal">×</button></div>${content}</section></div>`;setTimeout(()=>$('.modal input, .modal select, .modal button, .modal a')?.focus(),0);}
function closeModal(){$('#modal-root').innerHTML='';}
let toastTimer;
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function error(form,text){const el=form.querySelector('.error');if(el)el.textContent=text;else toast(text);}
function bookingDetails(id){const b=salon().bookings.find(x=>x.id===id);if(!b)return;modal('Appointment details',`<div class="row between"><h3>${esc(b.name)}</h3>${statusPill(b.status)}</div><div class="key-value"><span>Service</span><b>${esc(b.serviceName)}</b></div><div class="key-value"><span>Time</span><b>${humanDate(b.date)} · ${b.time}</b></div><div class="key-value"><span>Contact</span><b>${esc(b.email)}<br>${esc(b.phone)}</b></div><div class="key-value"><span>Price / deposit</span><b>${money(b.price)} / ${money(b.deposit)}</b></div><div class="row section-space">${b.status==='confirmed'?`<button class="btn primary" data-action="reschedule" data-id="${id}">Reschedule</button><button data-action="complete-booking" data-id="${id}">Mark completed</button><button class="danger" data-action="cancel-booking" data-id="${id}">Cancel</button>`:''}<a class="btn" href="#manage/${id}" data-action="close-modal">Customer manage page</a></div>`);}
function bookingForm(){const s=salon();if(!s.services.length){toast('Add a service first.');go('services');return;}modal('New manual appointment',`<form data-form="manual-booking"><label class="field">Service<select name="serviceId">${s.services.map(x=>`<option value="${x.id}">${esc(x.name)} · ${money(x.price)} · ${x.duration} min</option>`).join('')}</select></label><div class="grid two">${field('Date','date',nextDate(),'date',`min="${today()}" required`)}<label class="field">Time<select name="time" id="manual-times">${available(nextDate(),s.services[0].id).map(t=>`<option>${t}</option>`).join('')}</select></label></div>${field('Customer name','name','','text','required placeholder="Example customer"')}${field('Customer email','email','','email','required placeholder="customer@example.com"')}${field('Phone (optional)','phone','','tel')}<div class="error" role="alert"></div><div class="form-footer"><span class="tiny muted">Saved in this demo only.</span><button class="btn primary">Create appointment</button></div></form>`);}
function serviceForm(id){const x=salon().services.find(x=>x.id===id)||{name:'',price:25,duration:30};modal(id?'Edit service':'Add service',`<form data-form="service" data-id="${id||''}">${field('Service name','name',x.name,'text','required maxlength="100"')}<div class="grid two">${field('Price (£)','price',x.price,'number','min="0" max="2000" step="0.01" required')}${field('Duration (minutes)','duration',x.duration,'number','min="15" max="240" step="15" required')}</div><div class="error" role="alert"></div><button class="btn primary">Save service</button></form>`);}
function createBooking(data,source='Online'){
 const s=salon(),svc=s.services.find(x=>x.id===data.serviceId);
 if(!svc)throw Error('Choose a valid service.');
 if(!available(data.date,data.serviceId).includes(data.time))throw Error('That time is no longer available. Please choose another slot.');
 if(!data.name?.trim()||!data.email?.trim())throw Error('Add a customer name and email before confirming.');
 let c=s.customers.find(c=>c.email.toLowerCase()===data.email.toLowerCase());
 if(!c){c={id:uid('c'),name:data.name.trim(),email:data.email.trim(),phone:data.phone||''};s.customers.push(c);}
 const deposit=source==='Online'&&s.payments.enabled?Math.min(Number(s.payments.deposit),svc.price):0;
 const b={id:uid('bk'),serviceId:svc.id,serviceName:svc.name,duration:svc.duration,price:svc.price,date:data.date,time:data.time,customerId:c.id,name:data.name.trim(),email:data.email.trim(),phone:data.phone||'',source,status:'confirmed',deposit};
 s.bookings.push(b);if(deposit>0){const fee=Math.round((deposit*.015+.2)*100)/100;s.payments.transactions.unshift({id:uid('pay'),bookingId:b.id,name:b.name,amount:deposit,fee,net:Math.round((deposit-fee)*100)/100,method:data.method||'Card'});}
 notify('confirmed',b);save();return b;
}
function reschedule(id,date=nextDate()){const b=salon().bookings.find(x=>x.id===id);if(!b||b.status!=='confirmed')return;const times=available(date,b.serviceId,id);modal('Reschedule appointment',`<p>${esc(b.name)} · ${esc(b.serviceName)}<br>Currently ${humanDate(b.date)} at ${b.time}</p><form data-form="reschedule" data-id="${id}">${field('New date','date',date,'date',`required min="${today()}"`)}<label class="field">Available time<select name="time" required>${times.map(t=>`<option value="${t}">${t}</option>`).join('')||'<option value="">No available times</option>'}</select></label><div class="error" role="alert"></div><button class="btn primary">Save new time</button></form>`);}
function emailPreview(id){const e=salon().emails.find(x=>x.id===id);if(!e)return;const b=e.booking;modal('Email preview',`<div class="email"><p class="tiny"><b>From:</b> ${esc(e.from)}<br><b>To:</b> ${esc(e.to)}<br><b>Reply-To:</b> ${esc(e.reply)}<br><b>Subject:</b> ${esc(e.subject)}</p><article><div class="brand" style="font-size:19px">jova<em>book</em></div><h2 class="section-space">${e.kind==='cancelled'?'Appointment cancelled':e.kind==='rescheduled'?'Your new appointment time':e.kind==='reminder'?'See you soon':'Your booking is confirmed'}</h2><p>Hello ${esc(b.name)},</p><p>${esc(b.serviceName)} at <b>${esc(e.salonName)}</b><br>${humanDate(b.date)} at ${b.time}<br>${esc(e.address)}</p><p>Total: ${money(b.price)}<br>Deposit paid: ${money(b.deposit)}</p><a class="btn primary small" href="#manage/${b.id}" data-action="close-modal">Manage appointment</a><p class="tiny section-space">Powered by Jova Media. This email was simulated locally and has not been sent.</p></article></div>`);}
function chatSend(text){chat.push({role:'user',text});const s=salon();const svc=s.services.find(x=>text.toLowerCase().includes(x.name.toLowerCase())||x.name.toLowerCase().split(' ').some(w=>w.length>3&&text.toLowerCase().includes(w.replace(/s$/,''))));let reply;if(svc){draft={...defaultDraft(),serviceId:svc.id};const times=available(draft.date,svc.id);reply=`${svc.name} is ${money(svc.price)} and takes ${svc.duration} minutes. On ${humanDate(draft.date)}, the demo diary has ${times.slice(0,3).join(', ')||'no available slots'}. Choose “Continue to available times” to select a slot and confirm your details. I haven't booked anything yet.`;}else if(/price|cost|service|treatment|available|book/i.test(text))reply=`Our demo services are ${s.services.map(x=>x.name+' ('+money(x.price)+')').join(', ')}. Which would you like?`;else reply='This is a scripted preview, so I can help with the listed treatments only. Choose a treatment below, or use the booking page. An unsupported request would go to the salon in the real product.';chat.push({role:'assistant',text:reply});render();}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,s=salon();
 if(a==='screens')screens();else if(a==='close-modal')closeModal();
 else if(a==='sms-preview'){const b=s.bookings.find(b=>b.id===id);if(b)modal('Day-before SMS preview',`<p><b>To:</b> ${esc(b.phone)}</p><div class="email">Reminder: ${esc(s.name)}, ${esc(b.serviceName)}, tomorrow at ${b.time}. ${esc(s.address)}. Manage: [secure appointment link]</div><p class="demo-note section-space">Preview only. Kept short to reduce multi-segment charges. No real text sent.</p>`);}
 else if(a==='verify-login-preview'){closeModal();go('dashboard');toast('Sign-in screen preview completed. No real authentication performed.');}
 else if(a==='reset')modal('Reset demo?',`<p>This clears only JovaBook's local demo records and restores the example salon. It does not affect your real website, Stripe or other browser data.</p><button class="danger" data-action="reset-confirm">Reset local demonstration</button>`);
 else if(a==='reset-confirm'){state=fresh();save();draft={};chat=[];lastBooking=null;closeModal();go('plans');toast('Demo restored.');}
 else if(a==='policy')modal('Demo privacy information','<p>This preview stores example salon and booking data in this browser’s localStorage. No backend, analytics, email provider or payment processor is connected.</p><p>Use fictional details. The Reset demo button removes this app’s stored demo data. Production privacy information and secure authentication still need implementation.</p>');
 else if(a==='cookies')modal('Cookie settings','<p>This demo loads no analytics, advertising cookies or external embeds. It uses localStorage to retain the example data you create.</p><button class="btn primary" data-action="close-modal">Keep functional demo storage</button>');
 else if(a==='map-preview')modal('Map integration preview','<p>A production map can show the salon’s saved address. Optional third-party embeds should respect the site’s consent settings. No external map loads here.</p>');
 else if(a==='new-booking')bookingForm();else if(a==='booking-details')bookingDetails(id);
 else if(a==='complete-booking'){const b=s.bookings.find(x=>x.id===id);if(b)b.status='completed';save();closeModal();render();toast('Appointment marked completed.');}
 else if(a==='cancel-booking')modal('Cancel this appointment?',`<p>The time will become available again and a cancellation email will appear in the demo outbox. Any recorded deposit is not automatically refunded.</p><button class="danger" data-action="cancel-confirm" data-id="${id}">Cancel appointment</button>`);
 else if(a==='cancel-confirm'){const b=s.bookings.find(x=>x.id===id);if(b&&b.status==='confirmed'){b.status='cancelled';notify('cancelled',b);save();}closeModal();render();toast('Appointment cancelled. Slot released.');}
 else if(a==='reschedule')reschedule(id);
 else if(a==='calendar-prev'){calendarWeek=addDays(calendarWeek,-7);render();}else if(a==='calendar-next'){calendarWeek=addDays(calendarWeek,7);render();}else if(a==='calendar-now'){calendarWeek=today();render();}
 else if(a==='add-service')serviceForm();else if(a==='edit-service')serviceForm(id);
 else if(a==='remove-service')modal('Remove this service?',`<p>New customers will no longer be able to choose it. Existing bookings retain their service name, duration and price. Re-add a service later if needed.</p><button class="danger" data-action="remove-service-confirm" data-id="${id}">Remove service from menu</button>`);
 else if(a==='remove-service-confirm'){if(s.bookings.some(b=>b.serviceId===id&&b.status==='confirmed')){toast('This service has confirmed bookings. Complete or cancel them before removing it.');closeModal();}else{s.services=s.services.filter(x=>x.id!==id);save();closeModal();render();toast('Service removed.');}}
 else if(a==='customer'){const c=s.customers.find(x=>x.id===id);modal('Customer history',`<h3>${esc(c.name)}</h3><p>${esc(c.email)}<br>${esc(c.phone)}</p>${bookingTable(s.bookings.filter(b=>b.customerId===id).sort(sortBookings))}`,'large');}
 else if(a==='team-invite')modal('Staff invitation preview','<p>On Standard, the owner would enter a staff email, choose permissions and assign a bookable calendar.</p><div class="notice amber">Planned feature. No invitations are sent and Essential remains limited to one calendar.</div>');
 else if(a==='subscription-method'){paymentMethod=el.dataset.value;render();}else if(a==='customer-method'){draft.method=el.dataset.value;render();}
 else if(a==='select-service'){draft={...defaultDraft(),serviceId:id};go('book/time');}else if(a==='select-time'){draft.time=el.dataset.time;render();}
 else if(a==='confirm-booking'){try{const b=createBooking(draft);lastBooking=b.id;calendarWeek=b.date;go('book/confirmation');toast('Demo appointment saved. Confirmation added to outbox.');}catch(err){$('#booking-error').textContent=err.message;}}
 else if(a==='cancel-subscription')modal('Cancel your Jova subscription?',`<p>Your simulated renewal will stop. Existing demo appointments remain saved. This does not cancel treatment bookings or refund deposits.</p><button class="danger" data-action="cancel-sub-confirm">Cancel demo subscription</button>`);
 else if(a==='cancel-sub-confirm'){s.subscription.status='cancelled';save();closeModal();render();toast('Demo subscription cancelled.');}
 else if(a==='restart-trial'){s.subscription.status='trialing';s.subscription.trialEnd=new Date(Date.now()+3*86400000).toISOString();save();render();toast('Three-day demo trial restarted.');}
 else if(a==='billing-state'){s.subscription.status=el.dataset.value;save();render();toast(el.dataset.value==='active'?'Simulated £20 subscription payment. No money charged.':'Failed renewal simulated.');}
 else if(a==='portal')modal('Payment settings preview',`<p>In production this opens a secure Stripe billing portal. This local form only changes a demo label.</p><form data-form="portal">${field('Payment method label','method',s.subscription.method,'text','required maxlength="60"')}<button class="btn primary">Save demo payment label</button></form>`);
 else if(a==='onboard-next'){s.payments.stage=Math.min(2,s.payments.stage+1);save();render();}else if(a==='onboard-back'){s.payments.stage=Math.max(0,s.payments.stage-1);save();render();}
 else if(a==='onboard-complete'){s.payments.enabled=true;s.payments.deposit=10;save();go('payments');toast('Demo account connected. £10 example deposit enabled.');}
 else if(a==='reminders'){let n=0;for(const b of s.bookings.filter(x=>x.status==='confirmed'&&x.date>=today()))if(!s.emails.some(x=>x.kind==='reminder'&&x.booking.id===b.id&&x.booking.date===b.date&&x.booking.time===b.time)){notify('reminder',b);n++;}save();render();toast(`${n} demo reminders generated. Nothing was sent.`);}
 else if(a==='email')emailPreview(id);
 else if(a==='chat-prompt')chatSend(el.dataset.value);
 else if(a==='copy-link'){const link=location.origin+'/?salon='+encodeURIComponent(s.slug)+'#book/service';try{await navigator.clipboard.writeText(link);toast('Local booking link copied for '+s.name+'.');}catch{modal('Local booking link',`<p>Open this link in the same browser to use this salon's saved example data:</p><p class="mono">${esc(link)}</p>`);}}
 else if(a==='export'){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=s.slug+'-demo-export.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo salon export downloaded.');}
});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),type=form.dataset.form,s=salon();try{
 if(type==='login-preview'){modal('Check your email — screen preview',`<p>The real product would email a secure, expiring sign-in link to <b>${esc(data.email)}</b>.</p><div class="email"><b>Jova Bookings · Sign in to your salon</b><p class="section-space">Use this link to access your salon dashboard. If you did not request it, ignore this message.</p><button class="btn primary" data-action="verify-login-preview">Preview opening the sign-in link</button></div><p class="demo-note section-space">No email was sent. This button demonstrates the next screen only.</p>`);}
 else
 if(type==='signup'){const slug=data.slug.trim().toLowerCase();if(['www','app','admin','support','salon','api','bookings'].includes(slug))throw Error('That address is reserved. Choose another name.');if(state.salons.some(s=>s.slug===slug))throw Error('That booking address is already taken. Try another.');const n=seedSalon(uid('salon'),data.name.trim(),slug,'#77504e');n.owner=data.owner.trim();n.email=data.email.trim();n.staff[0].name=n.owner;n.bookings=[];n.customers=[];n.subscription.status='setup';n.subscription.method='';state.salons=[n];state.active=n.id;save();draft={};go('setup');}
 else if(type==='setup'||type==='settings'){const selected=new FormData(form).getAll('days').map(Number);if(!selected.length)throw Error('Select at least one opening day.');if(mins(data.start)>=mins(data.end))throw Error('Closing time must be later than opening time.');s.hours={start:data.start,end:data.end,days:selected};s.color=data.color;s.address=data.address;s.phone=data.phone;if(type==='setup'){const svc=s.services[0];if(svc)Object.assign(svc,{name:data.service,price:Number(data.price),duration:Number(data.duration)});save();go('checkout');}else{s.name=data.name.trim();s.initials=s.name.split(' ').slice(0,2).map(x=>x[0]).join('');s.email=data.email;s.about=data.about;s.buffer=Number(data.buffer);s.notice=Number(data.notice);save();render();toast('Salon settings saved.');}}
 else if(type==='checkout'){s.subscription={status:'trialing',plan:'Essential',trialEnd:new Date(Date.now()+3*86400000).toISOString(),method:paymentMethod==='Card'?'Demo card •••• 4242':paymentMethod+' demo wallet'};save();go('dashboard');toast('Three-day demo trial activated. No real subscription created.');}
 else if(type==='login'){state.active=data.salon;save();draft={};chat=[];go('dashboard');}
 else if(type==='manual-booking'){const b=createBooking(data,'Manual');calendarWeek=b.date;closeModal();go('calendar');toast('Manual appointment saved.');}
 else if(type==='service'){const id=form.dataset.id;const old=s.services.find(x=>x.id===id);const x={id:id||uid('svc'),name:data.name.trim(),price:Number(data.price),duration:Number(data.duration)};if(!x.name)throw Error('Enter a service name.');if(old)Object.assign(old,x);else s.services.push(x);save();closeModal();render();toast('Service saved.');}
 else if(type==='customer-details'){Object.assign(draft,{name:data.name.trim(),email:data.email.trim(),phone:data.phone.trim()});if(!draft.time||!available(draft.date,draft.serviceId).includes(draft.time))throw Error('Choose an available date and time first.');go('book/payment');}
 else if(type==='reschedule'){const b=s.bookings.find(x=>x.id===form.dataset.id);if(!available(data.date,b.serviceId,b.id).includes(data.time))throw Error('Choose a free time.');Object.assign(b,{date:data.date,time:data.time});notify('rescheduled',b);save();calendarWeek=b.date;closeModal();render();toast('Appointment rescheduled. Email preview updated.');}
 else if(type==='deposit'){s.payments.deposit=Number(data.amount);save();render();toast('Demo deposit amount saved.');}
 else if(type==='onboard-business'){s.payments.stage=1;save();render();}
 else if(type==='portal'){s.subscription.method=data.method.trim();save();closeModal();render();toast('Demo label saved.');}
 else if(type==='chat')chatSend(data.message.trim());
 }catch(err){error(form,err.message);}
});
document.addEventListener('change',e=>{const el=e.target,s=salon();if(el.dataset.change==='salon'){state.active=el.value;save();draft={};chat=[];search='';render();}else if(el.dataset.change==='booking-date'){draft.date=el.value;draft.time='';render();}const f=el.closest('[data-form]');if(f?.dataset.form==='manual-booking'&&(el.name==='date'||el.name==='serviceId')){const fd=new FormData(f);$('#manual-times').innerHTML=available(fd.get('date'),fd.get('serviceId')).map(t=>`<option>${t}</option>`).join('')||'<option value="">No available times</option>';}if(f?.dataset.form==='reschedule'&&el.name==='date'){const b=s.bookings.find(x=>x.id===f.dataset.id);const ts=available(el.value,b.serviceId,b.id);f.querySelector('[name=time]').innerHTML=ts.map(t=>`<option>${t}</option>`).join('')||'<option value="">No available times</option>';}});
document.addEventListener('input',e=>{const el=e.target,f=el.closest('[data-form]');if(f?.dataset.form==='signup'){if(el.name==='name'){f.elements.slug.value=idFor(el.value);$('#slug-preview').textContent=f.elements.slug.value||'yourname';}if(el.name==='slug')$('#slug-preview').textContent=el.value||'yourname';}if(el.id==='customer-search'){search=el.value;const pos=el.selectionStart;render();const input=$('#customer-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('.modal')){const list=[...$('.modal').querySelectorAll('button,a[href],input,select,textarea')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=JSON.parse(e.newValue);render();}catch{}}});
save();render();
})();
